std::vector<int> src = {1, 2, 3};
std::vector<int> dst;
// back_inserter uses push_back()
// Appends to the end, preserving order.

std::copy(src.begin(), src.end(),
          std::back_inserter(dst));

// dst is now {1, 2, 3}

// ------------------------------------

std::list<int> L_src = {10, 20, 30};
std::list<int> L_dst;
// front_inserter uses push_front()
// Only works on containers supporting push_front (list, deque).

std::transform(L_src.begin(), L_src.end(),
               std::front_inserter(L_dst),
               [](int x){ return x + 1; });

// L_dst is {31, 21, 11} (Order is reversed!)

// ------------------------------------

std::vector<int> V_src = {99, 100};
std::vector<int> V_dst = {1, 2, 3};
// inserter uses container.insert(pos, value)
// Insertion position remains constant (iterator advances).

auto pos = V_dst.begin();
std::advance(pos, 1); // Point to '2'

std::copy(V_src.begin(), V_src.end(),
          std::inserter(V_dst, pos));

// V_dst is {1, 99, 100, 2, 3} (Inserted before original '2')
